def fib(n):
    if n == 1 or n == 2:
        return 1
    else:
        return fib(n - 1) + fib(n - 2)

n = int(input())
print(fib(n))

def fac(n):
    if n == 0 or n == 1:
        return 1
    else:
        return n * fac(n - 1)

n = int(input())
print(fac(n))
